{"b0e31430-2b76-41f8-9c3a-8153624014da":{"id":"b0e31430-2b76-41f8-9c3a-8153624014da","createdAt":1761873459142,"updatedAt":1761873462622,"title":"Git Case Sensitivity Issue","messages":[{"id":"2650cf73-725f-4f0b-b36c-1059ae20d723","role":"user","content":[{"type":"text","text":"hey for some reason the background i added to my git isnt working but works locally look:  (.venv) sandro@MacBookPro git add -A"},{"type":"text","text":"(.venv) sandro@MacBookPro git commit -m "style changes""},{"type":"text","text":"[feature/my-branch f4e116d] style changes"},{"type":"text","text":" 9 files changed, 618 insertions(+), 26 deletions(-)"},{"type":"text","text":" create mode 100644 .idea/inspectionProfiles/profiles_settings.xml"},{"type":"text","text":" create mode 100644 .idea/misc.xml"},{"type":"text","text":" create mode 100644 .idea/vcs.xml"},{"type":"text","text":" create mode 100644 .idea/zencoder-chats-dedicated.xml"},{"type":"text","text":" create mode 100644 static/images/finaL_about_support_background.png"},{"type":"text","text":"(.venv) sandro@MacBookPro git push     "},{"type":"text","text":"Enumerating objects: 27, done."},{"type":"text","text":"Counting objects: 100% (27/27), done."},{"type":"text","text":"Delta compression using up to 8 threads"},{"type":"text","text":"Compressing objects: 100% (15/15), done."},{"type":"text","text":"Writing objects: 100% (17/17), 1.97 MiB | 52.95 MiB/s, done."},{"type":"text","text":"Total 17 (delta 5), reused 0 (delta 0), pack-reused 0"},{"type":"text","text":"remote: Resolving deltas: 100% (5/5), completed with 5 local objects."},{"type":"text","text":"To https://github.com/sandroescobar/miamiMkt.git"},{"type":"text","text":"   95f1250..f4e116d  feature/my-branch -> feature/my-branch"},{"type":"text","text":"(.venv) sandro@MacBookPro git add -A"},{"type":"text","text":"(.venv) sandro@MacBookPro git commit -m "about page change""},{"type":"text","text":"[feature/my-branch 1309217] about page change"},{"type":"text","text":" 1 fi